import { describe, expect, it } from "vitest";
import { OpenClawSchema } from "./zod-schema.js";

describe("telegram disableAudioPreflight schema", () => {
  it("accepts disableAudioPreflight for groups and topics", () => {
    const res = OpenClawSchema.safeParse({
      channels: {
        telegram: {
          groups: {
            "*": {
              requireMention: true,
              disableAudioPreflight: true,
              topics: {
                "123": {
                  disableAudioPreflight: false,
                },
              },
            },
          },
        },
      },
    });

    expect(res.success).toBe(true);
    if (!res.success) {
      return;
    }

    const group = res.data.channels?.telegram?.groups?.["*"];
    expect(group?.disableAudioPreflight).toBe(true);
    expect(group?.topics?.["123"]?.disableAudioPreflight).toBe(false);
  });

  it("rejects non-boolean disableAudioPreflight values", () => {
    const res = OpenClawSchema.safeParse({
      channels: {
        telegram: {
          groups: {
            "*": {
              disableAudioPreflight: "yes",
            },
          },
        },
      },
    });

    expect(res.success).toBe(false);
  });
});

const DEFAULT_RESET_TRIGGERS = ["/new", "/reset"] as const;

type FeishuBeforeResetContext = {
  cfg: Record<string, unknown>;
  sessionEntry: Record<string, unknown>;
  previousSessionEntry?: Record<string, unknown>;
  commandSource: string;
  timestamp: number;
};

type FeishuBeforeResetEvent = {
  type: "command";
  action: "new" | "reset";
  context: FeishuBeforeResetContext;
};

type FeishuBeforeResetRunner = {
  runBeforeReset: (
    event: FeishuBeforeResetEvent,
    ctx: { agentId: string; sessionKey: string },
  ) => Promise<void>;
};

/**
 * Handle Feishu command messages and trigger reset hooks.
 */
export async function handleFeishuCommand(
  messageText: string,
  sessionKey: string,
  hookRunner: FeishuBeforeResetRunner,
  context: FeishuBeforeResetContext,
): Promise<boolean> {
  const trimmed = messageText.trim().toLowerCase();
  const isResetCommand = DEFAULT_RESET_TRIGGERS.some(
    (trigger) => trimmed === trigger || trimmed.startsWith(`${trigger} `),
  );
  if (!isResetCommand) {
    return false;
  }

  const command = trimmed.split(" ")[0];
  const action: "new" | "reset" = command === "/new" ? "new" : "reset";
  await hookRunner.runBeforeReset(
    {
      type: "command",
      action,
      context: {
        ...context,
        commandSource: "feishu",
      },
    },
    {
      agentId: "main",
      sessionKey,
    },
  );

  return true;
}

